<div class="d-flex flex-wrap gap-2 mb-3"><a class="btn btn-sm btn-light" href="<?= site_url('admin/inspections') ?>">All</a><?php foreach ($statuses as $k => $l): ?><a class="btn btn-sm <?= service('request')->getGet('status') === $k ? 'btn-primary' : 'btn-light' ?>" href="<?= site_url('admin/inspections?status=' . $k) ?>"><?= esc($l) ?></a><?php endforeach ?></div>
